@startuml

class Organizer {
  + firstName : string
  + lastName : string
  + email : string
  + postalAddress : string
  + phoneNumber : string
  + password : string
}

class EventType {
  + name : string
}

class Event {
  + occasion : string
  + startDateTime : datetime
  + endDateTime : datetime
}

class Location {
  + name : string
  + address : string
}

class Attendee {
  + firstName : string
  + lastName : string
  + email : string
  + password : string
  + attendanceStatus : string
}

class Task {
  + description : string
  + status : string
}

class TaskAssignment {
  + isCompleted : boolean
}

Organizer "1..*" -- "1" Event : organizes
Event "1" -- "1" EventType
Event "1" -- "1" Location
Event "1" -- "*" Task
Event "1" -- "*" Attendee : invites
Organizer "0..1" -- "0..*" Attendee : attends

Attendee "1" -- "*" TaskAssignment : performs
Task "1" -- "*" TaskAssignment : is assigned to

@enduml

